const SANITY_DATASET = 'production';
const SANITY_API_VERSION = 'v2024-01-01';

async function uploadArticle(article) {
  const mutation = {
    mutations: [{
      create: {
        _type: 'post',
        title: { en: article.title, zh: article.titleZh },
        titleZh: article.titleZh,
        slug: { current: article.slug },
        category: 'technical',
        excerpt: { en: article.excerpt, zh: article.excerptZh },
        excerptZh: article.excerptZh,
        content: article.content,
        contentZh: article.contentZh,
        coverImage: article.coverImage,
        language: 'en',
        publishedAt: article.publishedAt || '2025-03-01T00:00:00Z'
      }
    }]
  };

  const response = await fetch(
    `https://${SANITY_PROJECT_ID}.api.sanity.io/${SANITY_API_VERSION}/data/mutate/${SANITY_DATASET}?returnIds=true`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${SANITY_API_TOKEN}`
      },
      body: JSON.stringify(mutation)
    }
  );

  const result = await response.json();
  
  if (result.results && result.results.length > 0) {
    console.log(`✅ Article uploaded: ${article.title}`);
    console.log(`   ID: ${result.results[0].id}`);
    return { success: true, id: result.results[0].id };
  } else {
    console.error(`❌ Failed to upload: ${article.title}`);
    console.error('Error:', result);
    return { success: false, error: result };
  }
}

